// CSD_RATIONALE_BEGIN
// Strategy: 
// - Start in an unconstrained phase where we generate free-form reasoning text.
// - Transition to a constrained phase when we encounter '<<'.
// - In the constrained phase, use SoftConstrainedStep to generate arithmetic expressions.
// - Apply penalties on '>>' to prevent premature closure of expressions.
// - Monitor for grammar dead-ends and revert to unconstrained mode if necessary.
// This approach allows us to balance between free-form reasoning and structured arithmetic generation.
// CSD_RATIONALE_END

generated := [];
var steps := 0;
var insideConstrained := false;
var currentConstrained: Prefix := [];
while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant |generated| == steps
  invariant lm.ValidTokensIdsLogits()
  invariant insideConstrained ==> parser.IsValidPrefix(currentConstrained)
  invariant insideConstrained ==> forall t: Token ::
    t in parser.ValidNextTokens(currentConstrained) ==> t in lm.Tokens
  invariant helpers.cost == steps
  decreases maxSteps - steps
{
  if !insideConstrained {
    // UNCONSTRAINED PHASE: generate reasoning text
    lm.GenerateLogits(prompt + generated);

    // Penalty on '>>' to discourage premature expression closure
    if ">>" in lm.Tokens {
      helpers.PenalizeTokenLogits(lm, [">>"], 3.0);
    }

    var next := helpers.UnconstrainedStep(lm, prompt + generated);
    helpers.cost := helpers.cost + 1;

    if next == eosToken { break; }
    generated := generated + [next];
    steps := steps + 1;

    // Detect '<<' to enter constrained mode
    if CSDHelpers.Contains(next, "<<") {
      insideConstrained := true;
      currentConstrained := [];
      CSDHelpers.RollbackPreservesTokenInvariant(lm, parser, []);
    }
  } else {
    // CONSTRAINED PHASE: grammar-enforced expression generation

    // Dead-end detection: bail if grammar too narrow
    var narrow := helpers.DeadEndDetection(parser, currentConstrained, 3);
    if narrow || parser.IsCompletePrefix(currentConstrained) {
      insideConstrained := false;
    } else {
      // Soft constraint: boost valid tokens by 5.0 (not hard mask)
      lm.GenerateLogits(prompt + generated);

      // Penalty on '>>' when expression is short (< 5 tokens)
      if |currentConstrained| < 5 && ">>" in lm.Tokens {
        helpers.PenalizeTokenLogits(lm, [">>"], 3.0);
      }

      var validTokens := parser.ValidNextTokens(currentConstrained);
      helpers.BoostTokenLogits(lm, validTokens, 5.0);

      var (next, isValid) := helpers.SoftConstrainedStep(lm, parser, prompt + generated, currentConstrained);
      helpers.cost := helpers.cost + 1;
      generated := generated + [next];
      steps := steps + 1;

      if parser.IsValidPrefix(currentConstrained + [next]) {
        currentConstrained := currentConstrained + [next];
        if CSDHelpers.Contains(next, ">>") {
          insideConstrained := false;
        }
      } else {
        // Soft constraint allowed invalid token — abandon window
        insideConstrained := false;
      }
    }
  }
}
cost := helpers.cost;

